import Foundation
import CoreML
import CoreVideo
import Accelerate

// DEC-130/131: on-device LEARNED shot front-end. A Swift/CoreML parity port of ops/detector_integrate.py: run the
// BallLaneDetector CenterNet on each (letterboxed) frame, decode the ball heat-map peak + the lane-geometry head.
// Used as the FALLBACK when the classical on-device tracker fails (BALL_TRACK_NOT_FOUND / sparse), so the on-device
// engine covers the same hard camera positions the server's learned path does. The compiled model class
// (`BallLaneDetector`) is generated by Xcode from Models/BallLaneDetector.mlpackage; absent → `shared` is nil and
// the caller stays classical-only.
nonisolated struct ODBallDet { let cx: Float; let cy: Float; let score: Float }
nonisolated struct ODLaneParams { let foulL: (Float, Float); let foulR: (Float, Float); let vp: (Float, Float) }

nonisolated final class OnDeviceLearnedDetector: @unchecked Sendable {   // immutable after init; MLModel is thread-safe
    static let shared: OnDeviceLearnedDetector? = {
        guard let d = try? OnDeviceLearnedDetector() else { return nil }
        return d
    }()

    private let model: MLModel
    private let input = 512
    private let mean: [Float] = [0.485, 0.456, 0.406]
    private let std: [Float] = [0.229, 0.224, 0.225]

    init() throws {
        // The generated class exposes its compiled URL; load the bare MLModel so we can read named outputs.
        guard let url = Bundle.main.url(forResource: "BallLaneDetector", withExtension: "mlmodelc") else {
            throw NSError(domain: "ls.learned", code: 1)
        }
        let cfg = MLModelConfiguration(); cfg.computeUnits = .all
        self.model = try MLModel(contentsOf: url, configuration: cfg)
    }

    /// Run the detector on one BGRA frame. Returns the ball peak (full-frame coords) over `thr`, and the lane params.
    func detect(_ px: CVPixelBuffer, rot: ODRotation, thr: Float = 0.3) -> (ball: ODBallDet?, lane: ODLaneParams?) {
        guard let buf = OnDeviceDecode.rotated(px, rot) else { return (nil, nil) }
        CVPixelBufferLockBaseAddress(buf, .readOnly); defer { CVPixelBufferUnlockBaseAddress(buf, .readOnly) }
        let W = CVPixelBufferGetWidth(buf), H = CVPixelBufferGetHeight(buf)
        let rb = CVPixelBufferGetBytesPerRow(buf)
        guard let base = CVPixelBufferGetBaseAddress(buf)?.assumingMemoryBound(to: UInt8.self) else { return (nil, nil) }
        let s = Float(input) / Float(max(W, H))                    // letterbox scale (match detector_integrate)
        let nw = Int((Float(W) * s).rounded()), nh = Int((Float(H) * s).rounded())
        guard let arr = try? MLMultiArray(shape: [1, 3, NSNumber(value: input), NSNumber(value: input)], dataType: .float32) else { return (nil, nil) }
        let ptr = arr.dataPointer.assumingMemoryBound(to: Float.self)
        let plane = input * input
        memset(ptr, 0, plane * 3 * MemoryLayout<Float>.size)      // zero-pad the letterbox border
        for yy in 0..<nh {
            let sy = min(Int(Float(yy) / s), H - 1)
            for xx in 0..<nw {
                let sx = min(Int(Float(xx) / s), W - 1)
                let p = sy * rb + sx * 4                            // BGRA
                let r = Float(base[p + 2]) / 255, g = Float(base[p + 1]) / 255, b = Float(base[p]) / 255
                let o = yy * input + xx
                ptr[o] = (r - mean[0]) / std[0]                    // channel 0 = R
                ptr[plane + o] = (g - mean[1]) / std[1]
                ptr[2 * plane + o] = (b - mean[2]) / std[2]
            }
        }
        guard let out = try? model.prediction(from: MLDictionaryFeatureProvider(dictionary: ["image": arr])) else { return (nil, nil) }
        guard let hm = out.featureValue(for: "heatmap")?.multiArrayValue,
              let lane = out.featureValue(for: "lane")?.multiArrayValue else { return (nil, nil) }
        // heatmap shape [1, C, O, O] (C>=1, ball = channel 0), stride-4 output
        let O = hm.shape[hm.shape.count - 1].intValue
        let st = input / O
        let hp = hm.dataPointer.assumingMemoryBound(to: Float.self)
        var best: Float = thr; var bi = -1
        for i in 0..<(O * O) { if hp[i] > best { best = hp[i]; bi = i } }   // ball channel is first O*O block
        var ball: ODBallDet? = nil
        if bi >= 0 {
            let hy = bi / O, hx = bi % O
            ball = ODBallDet(cx: Float(hx * st) / s, cy: Float(hy * st) / s, score: best)   // letterbox → full frame
        }
        // lane head: 6 params normalized by max(W,H) (match lane_from_params)
        let lp = lane.dataPointer.assumingMemoryBound(to: Float.self)
        let m = Float(max(W, H))
        let lane6 = ODLaneParams(foulL: (lp[0] * m, lp[1] * m), foulR: (lp[2] * m, lp[3] * m), vp: (lp[4] * m, lp[5] * m))
        return (ball, lane6)
    }
}
